recipes.code:
{
  "inputs": [
    {
      "id": "ai-rete-rag-api-key",
      "type": "promptString",
      "description": "Your ai·rete·rag API key (create one at ai-rete-rag.com under Settings -> API Keys). Authenticates calls and ties them to your plan quota.",
      "password": true
    }
  ],
  "servers": {
    "ai-rete-rag": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "ai-rete-rag-mcp@0.5.3"
      ],
      "env": {
        "AI_RETE_RAG_API_KEY": "${input:ai-rete-rag-api-key}",
        "AI_RETE_RAG_API_URL": "<ai-rete-rag-api-url>"
      }
    }
  }
}
